from pathlib import Path
import duckdb
base=Path(r'D:\repository\数据湖\data\cnequity')
def ds(p): return sum(f.stat().st_size for f in p.rglob('*') if f.is_file())
print('=== data/cnequity 子树 ===')
for sub in sorted(base.iterdir(), key=lambda x:-(ds(x) if x.is_dir() else x.stat().st_size)):
    if sub.is_dir(): print(f'  {ds(sub)/1e6:8.1f} MB  {sub.name}/')
print('\n=== curated 各表 ===')
for sub in sorted((base/'curated').iterdir(), key=lambda x:-ds(x)):
    if sub.is_dir(): print(f'  {ds(sub)/1e6:8.1f} MB  {sub.name}')
print('\n=== derived 各表 ===')
for sub in sorted((base/'derived').iterdir(), key=lambda x:-ds(x)):
    if sub.is_dir(): print(f'  {ds(sub)/1e6:8.1f} MB  {sub.name}')
print('\n=== meta 各子树 ===')
meta=base/'meta'
for sub in sorted(meta.iterdir(), key=lambda x:-(ds(x) if x.is_dir() else x.stat().st_size)):
    if sub.is_dir(): print(f'  {ds(sub)/1e6:8.1f} MB  {sub.name}/')
print('\n=== revisions/data 各数据集(当前版本) ===')
rev=meta/'revisions'/'data'
if rev.exists():
    for sub in sorted(rev.iterdir(), key=lambda x:-ds(x)):
        if sub.is_dir(): print(f'  {ds(sub)/1e6:8.1f} MB  {sub.name}')
print('\n=== 全库最大文件 top12 ===')
files=sorted([f for f in base.rglob('*') if f.is_file()], key=lambda x:-x.stat().st_size)[:12]
for f in files: print(f'  {f.stat().st_size/1e6:8.1f} MB  {str(f.relative_to(base))}')
